import { useInfiniteQuery } from '@tanstack/react-query'
import './App.css'

interface FeedItem {
  id: number
  title: string
  body: string
  timestamp: string
}

interface FeedPage {
  items: FeedItem[]
  nextCursor: number | null
}

// Generate 30 mock items to support pagination testing
const MOCK_ITEMS: FeedItem[] = Array.from({ length: 30 }, (_, i) => ({
  id: i + 1,
  title: `Feed Item #${i + 1}`,
  body: `This is the body content for feed item number ${i + 1}. It represents a post in our infinite scrolling feed, loaded dynamically using TanStack Query.`,
  timestamp: new Date(Date.now() - i * 3600000).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
  }),
}))

// Mock API function with artificial delay
const fetchFeed = async ({ pageParam = 0 }: { pageParam: number }): Promise<FeedPage> => {
  // Simulate 500ms network latency
  await new Promise((resolve) => setTimeout(resolve, 500))

  const limit = 5
  const startIndex = pageParam
  const endIndex = startIndex + limit
  const items = MOCK_ITEMS.slice(startIndex, endIndex)
  const nextCursor = endIndex < MOCK_ITEMS.length ? endIndex : null

  return {
    items,
    nextCursor,
  }
}

function App() {
  const {
    data,
    error,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    status,
  } = useInfiniteQuery({
    queryKey: ['feed'],
    queryFn: ({ pageParam }) => fetchFeed({ pageParam }),
    initialPageParam: 0,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
  })

  return (
    <div className="feed-container">
      <header className="feed-header">
        <h1>Infinite Scroll Feed</h1>
        <p className="feed-subtitle">Powered by TanStack Query</p>
      </header>

      <main className="feed-main">
        {status === 'pending' ? (
          <div className="status-message">Loading feed...</div>
        ) : status === 'error' ? (
          <div className="status-message error">
            Error loading feed: {error instanceof Error ? error.message : 'Unknown error'}
          </div>
        ) : (
          <div className="feed-list">
            {data.pages.map((page, pageIndex) => (
              <div key={pageIndex} className="feed-page">
                {page.items.map((item) => (
                  <article key={item.id} className="feed-card">
                    <div className="feed-card-header">
                      <span className="feed-card-author">User {item.id}</span>
                      <span className="feed-card-time">{item.timestamp}</span>
                    </div>
                    <h2 className="feed-card-title">{item.title}</h2>
                    <p className="feed-card-body">{item.body}</p>
                  </article>
                ))}
              </div>
            ))}

            <div className="feed-actions">
              {isFetchingNextPage && (
                <div className="status-message">Loading more items...</div>
              )}

              <button
                type="button"
                className="load-more-btn"
                onClick={() => fetchNextPage()}
                disabled={!hasNextPage || isFetchingNextPage}
              >
                Load More
              </button>

              {!hasNextPage && (
                <p className="no-more-items">You have reached the end of the feed.</p>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  )
}

export default App

.feed-container {
  max-width: 600px;
  margin: 0 auto;
  padding: 40px 20px;
  text-align: left;
}

.feed-header {
  margin-bottom: 40px;
  text-align: center;
  border-bottom: 1px solid var(--border);
  padding-bottom: 20px;
}

.feed-header h1 {
  margin: 0 0 10px 0;
  font-size: 2.5rem;
  color: var(--text-h);
}

.feed-subtitle {
  color: var(--text);
  font-size: 1.1rem;
  margin: 0;
}

.feed-main {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.status-message {
  text-align: center;
  padding: 20px;
  color: var(--text);
  font-size: 1.1rem;
}

.status-message.error {
  color: #ef4444;
  background-color: #fef2f2;
  border: 1px solid #fee2e2;
  border-radius: 8px;
}

.feed-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.feed-page {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.feed-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  box-shadow: var(--shadow);
  transition: transform 0.2s, box-shadow 0.2s;
}

.feed-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 20px -8px rgba(0,0,0,0.15);
}

.feed-card-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 12px;
  font-size: 0.85rem;
  color: var(--text);
}

.feed-card-author {
  font-weight: 600;
  color: var(--accent);
}

.feed-card-time {
  opacity: 0.8;
}

.feed-card-title {
  margin: 0 0 12px 0;
  font-size: 1.4rem;
  color: var(--text-h);
}

.feed-card-body {
  margin: 0;
  line-height: 1.6;
  color: var(--text);
}

.feed-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  margin-top: 30px;
  padding-top: 20px;
  border-top: 1px solid var(--border);
}

.load-more-btn {
  font-family: var(--sans);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border-radius: 8px;
  background-color: var(--accent);
  color: #fff;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, opacity 0.2s;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.load-more-btn:hover:not(:disabled) {
  background-color: #9333ea;
}

.load-more-btn:disabled {
  background-color: var(--border);
  color: var(--text);
  cursor: not-allowed;
  box-shadow: none;
  opacity: 0.6;
}

.no-more-items {
  color: var(--text);
  font-size: 0.95rem;
  margin: 10px 0 0 0;
}
